<?php
namespace App\Features\Ai\Services;
use App\Features\Ai\Contracts\AiClientInterface;use Illuminate\Support\Facades\Http;use RuntimeException;
class OpenAiStockGeneratorService implements AiClientInterface {public function generate(string $prompt,int $count=5):array{$key=config('openai.api_key');if(!$key)throw new RuntimeException('OPENAI_API_KEY belum dikonfigurasi.');$response=Http::withToken($key)->timeout(45)->post(rtrim(config('openai.base_url'),'/').'/chat/completions',['model'=>config('openai.model'),'response_format'=>['type'=>'json_object'],'messages'=>[['role'=>'system','content'=>'Buat data contoh inventaris yang masuk akal. Balas JSON object dengan key items berisi array objek: name, sku, description, quantity, unit, price, min_stock. Jangan sertakan markdown.'],['role'=>'user','content'=>"Buat {$count} item stok untuk konteks: {$prompt}"]]])->throw()->json();$content=$response['choices'][0]['message']['content']??'{}';$items=json_decode($content,true)['items']??[];return array_values(array_filter($items,fn($x)=>is_array($x)&&!empty($x['name'])));}}
